public class MainActivity extends Activity {
 final int RED=0xffff3535,BG=0xff090909,PANEL=0xff1b1b1b,GRAY=0xffb5b5b5,WHITE=0xfff5f5f5; LinearLayout root,body,nav; ScrollView scroll; TextView status,selection; android.content.SharedPreferences prefs; Set<String> protectedKeys,protectedPaths,trees; ScanEngine.Result result; ExecutorService worker=Executors.newSingleThreadExecutor(),thumbs=Executors.newFixedThreadPool(2); Future<?> job; boolean busy; int scanMode=1,threshold=8,page=0; String scanStatus=""; final Handler filterHandler=new Handler(Looper.getMainLooper()); final ExecutorService filters=Executors.newSingleThreadExecutor(); Runnable filterPending; int filterGeneration; volatile int thumbGeneration; final android.util.LruCache<String,android.graphics.Bitmap> thumbCache=new android.util.LruCache<String,android.graphics.Bitmap>(24*1024*1024){@Override protected int sizeOf(String key,android.graphics.Bitmap b){return b.getAllocationByteCount();}}; String tab="홈"; ArrayList<ScanEngine.Item> pending=new ArrayList<>(); boolean restoring; static final int REQ_PERMISSION=12,REQ_TREE=13,REQ_TRASH=14;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("cleaner",0);protectedKeys=set("protected");protectedPaths=set("paths");trees=set("trees");scanMode=Math.max(0,Math.min(2,prefs.getInt("scanMode",1)));threshold=prefs.getInt("threshold",8);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(14),dp(8),dp(14),dp(8));root.setOnApplyWindowInsetsListener((v,in)->{android.graphics.Insets a=in.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(14)+a.left,dp(8)+a.top,dp(14)+a.right,dp(8)+a.bottom);return in;});setContentView(root);show();if("com.sanai.cleaner.OPEN_SCAN".equals(getIntent().getAction()))startScan();}
 Set<String> set(String k){return new HashSet<>(prefs.getStringSet(k,Collections.emptySet()));} void save(String k,Set<String> s){prefs.edit().putStringSet(k,new HashSet<>(s)).apply();} int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);} static String bytes(long n){if(n>=1e9)return String.format(Locale.KOREA,"%.2f GB",n/1e9);if(n>=1e6)return String.format(Locale.KOREA,"%.1f MB",n/1e6);if(n>=1000)return String.format(Locale.KOREA,"%.1f KB",n/1e3);return n+" B";}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;} TextView txt(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(4),0,dp(4));return t;} TextView bold(String s,int size,int color){TextView t=txt(s,size,color);t.setTypeface(null,Typeface.BOLD);return t;} void add(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(-1,-2));} void weight(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(0,-2,1));} void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));} LinearLayout card(LinearLayout parent){LinearLayout l=col();l.setBackground(bg(PANEL,16));l.setPadding(dp(12),dp(12),dp(12),dp(12));add(parent,l);gap(parent,9);return l;} Button btn(String s,boolean primary,Runnable run){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(WHITE);b.setTextSize(13);b.setBackground(bg(primary?0xffb80f18:0xff333333,10));b.setPadding(dp(8),dp(10),dp(8),dp(10));b.setOnClickListener(v->run.run());return b;} void button(LinearLayout l,String s,boolean primary,Runnable r){add(l,btn(s,primary,r));gap(l,6);} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void show(){filterGeneration++;thumbGeneration++;if(filterPending!=null)filterHandler.removeCallbacks(filterPending);root.removeAllViews();LinearLayout header=row();ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.chad);header.addView(icon,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout h=col();h.setPadding(dp(10),0,0,0);add(h,bold("사나이청소기",24,WHITE));add(h,txt("SANAI CLEANER  ·  v0.2.0",11,GRAY));weight(header,h);add(root,header);gap(root,8);status=txt(busy?(scanStatus.isEmpty()?"작업 실행 중…":scanStatus):"BRO, 불필요한 파일만 털어내라.",12,GRAY);add(root,status);scroll=new ScrollView(this);body=col();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));selection=txt("",13,RED);add(root,selection);nav=row();for(String name:new String[]{"홈","그룹","파일","보호","기록"}){Button b=btn(name,tab.equals(name),()->{tab=name;page=0;show();});weight(nav,b);}add(root,nav);switch(tab){case "홈":home();break;case "그룹":groups();break;case "파일":files();break;case "보호":protection();break;case "기록":history();break;}updateSelection();}
 void home(){StatFs s=new StatFs(Environment.getDataDirectory().getPath());long total=s.getTotalBytes(),free=s.getAvailableBytes();LinearLayout box=card(body);add(box,txt("기기 저장공간",14,GRAY));add(box,bold(bytes(free)+" 여유",30,RED));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress((int)(100*(total-free)/Math.max(1,total)));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(RED));add(box,bar);add(box,txt(bytes(total-free)+" 사용 / "+bytes(total),13,GRAY));if(result!=null){add(box,bold("정리 검토 후보 "+bytes(result.candidates()),20,WHITE));add(box,txt(result.items.size()+"개 분석 · 오류 "+result.errors+" · 휴지통 이동 즉시 공간 확보 아님",12,GRAY));}else add(box,txt("스캔 모드를 선택해 실제 데이터를 확인하라.",14,WHITE));button(box,busy?"작업 진행 중":new String[]{"초고속 스캔 시작","스마트 스캔 시작","정밀 스캔 시작"}[scanMode],true,()->{if(busy){toast("작업 중에는 다른 작업을 시작할 수 없다.");}else startScan();});button(body,"사진·영상·음악 접근 권한",false,this::requestAccess);button(body,"일반 파일 폴더 추가 (SAF)",false,this::chooseTree);button(body,"시스템 저장공간 / 앱 캐시 설정",false,()->settings(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button(body,"사용 빈도 낮은 앱 확인",false,this::apps);LinearLayout options=card(body);add(options,bold("스캔 모드",16,WHITE));String[] modes={"초고속 · 메타데이터/완전 중복","스마트 · 사진/영상 특징 + 필요한 AI","정밀 · 전체 사진 AI + 영상 5프레임"};RadioGroup choices=new RadioGroup(this);choices.setOrientation(RadioGroup.VERTICAL);for(int k=0;k<modes.length;k++){RadioButton rb=new RadioButton(this);rb.setId(View.generateViewId());rb.setText(modes[k]);rb.setTextColor(WHITE);rb.setEnabled(!busy);final int selected=k;choices.addView(rb);if(k==scanMode)choices.check(rb.getId());rb.setOnClickListener(v->{if(busy)return;scanMode=selected;prefs.edit().putInt("scanMode",selected).apply();show();});}add(options,choices);add(options,txt("초고속은 유사 그룹/AI 분석을 생략한다. 스마트는 기본 추천.",12,GRAY));add(options,txt("유사도 탐색 범위: "+threshold+" / 16 (높을수록 넓게)",12,GRAY));SeekBar sk=new SeekBar(this);sk.setMax(12);sk.setProgress(threshold-4);sk.setEnabled(!busy);sk.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){threshold=4+s.getProgress();prefs.edit().putInt("threshold",threshold).apply();show();}public void onProgressChanged(SeekBar s,int n,boolean user){}});add(options,sk);button(body,"업데이트 센터 · 서명된 분석 정책",false,this::updateCenter);if(result!=null){button(body,"저장공간 지도",false,this::storageMap);button(body,"완전 중복 / 유사 사진·영상·파일 그룹 보기",true,()->{tab="그룹";page=0;show();});button(body,"파일별 분석 및 후보 검토",false,()->{tab="파일";page=0;show();});}}
 void settings(String action){try{startActivity(new Intent(action));}catch(Exception e){toast("설정에서 직접 확인하라.");}}
 void requestAccess(){if(busy)return;if(Build.VERSION.SDK_INT>=33){ArrayList<String> p=new ArrayList<>(Arrays.asList(Manifest.permission.READ_MEDIA_IMAGES,Manifest.permission.READ_MEDIA_VIDEO,Manifest.permission.READ_MEDIA_AUDIO));if(Build.VERSION.SDK_INT>=34)p.add(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED);requestPermissions(p.toArray(new String[0]),REQ_PERMISSION);}else requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE},REQ_PERMISSION);}
 boolean access(){return Build.VERSION.SDK_INT>=33?(checkSelfPermission(Manifest.permission.READ_MEDIA_IMAGES)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.READ_MEDIA_VIDEO)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)==PackageManager.PERMISSION_GRANTED||(Build.VERSION.SDK_INT>=34&&checkSelfPermission(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED)==PackageManager.PERMISSION_GRANTED)):checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
 void chooseTree(){if(busy){toast("스캔 종료 후 추가하라.");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,REQ_TREE);}
 @Override public void onRequestPermissionsResult(int req,String[] p,int[] g){super.onRequestPermissionsResult(req,p,g);if(req==REQ_PERMISSION){if(access())startScan();else toast("허용된 파일만 분석 가능하다.");}}
 void startScan(){if(busy||!pending.isEmpty()||restoring)return;if(!access()&&trees.isEmpty()){requestAccess();return;}busy=true;scanStatus="파일 목록 확인 중…";result=null;show();final Set<String> p=new HashSet<>(protectedKeys),paths=new HashSet<>(protectedPaths),t=new HashSet<>(trees);final int th=threshold;final int d=scanMode;job=worker.submit(()->{try{ScanEngine.Result rr=new ScanEngine(getApplicationContext(),p,paths,th,d,s->runOnUiThread(()->{if(!isDestroyed()){scanStatus=s;status.setText(s);}})).run(t);rr.items.sort(Comparator.comparingInt((ScanEngine.Item i)->i.score).reversed().thenComparing(Comparator.comparingLong((ScanEngine.Item i)->i.size).reversed()));if(!rr.partial&&!Thread.currentThread().isInterrupted())runOnUiThread(()->{if(isDestroyed())return;result=rr;prefs.edit().putLong("candidate",rr.candidates()).apply();CleanerWidget.refresh(this);});}catch(Exception e){runOnUiThread(()->toast("스캔 오류: "+e.getClass().getSimpleName()));}finally{runOnUiThread(()->{if(!isDestroyed()){busy=false;show();}});}});}
 void storageMap(){if(result==null)return;Map<String,Long> map=new HashMap<>();for(ScanEngine.Item i:result.items)map.merge(i.path.isEmpty()?"(기타)":i.path,i.size,Long::sum);ArrayList<Map.Entry<String,Long>> rows=new ArrayList<>(map.entrySet());rows.sort((a,b)->Long.compare(b.getValue(),a.getValue()));LinearLayout l=col();l.setPadding(dp(12),dp(8),dp(12),dp(8));long max=rows.isEmpty()?1:Math.max(1,rows.get(0).getValue());for(Map.Entry<String,Long> e:rows){add(l,txt(e.getKey()+" · "+bytes(e.getValue()),13,WHITE));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress((int)(100.0*e.getValue()/max));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(RED));add(l,bar);}ScrollView sc=new ScrollView(this);sc.addView(l);new AlertDialog.Builder(this).setTitle("접근 가능한 폴더 용량").setView(sc).setPositiveButton("닫기",null).show();}
 void noScan(){add(body,txt("아직 스캔 결과가 없다.",15,GRAY));button(body,"홈에서 스캔",true,()->{tab="홈";show();startScan();});}
 void groups(){if(result==null){noScan();return;}ArrayList<ScanEngine.Group> all=new ArrayList<>(result.exact);all.addAll(result.similar);add(body,bold("완전 중복 "+result.exact.size()+" · 유사 그룹 "+result.similar.size(),19,WHITE));add(body,txt("추천은 확률이 아니다. 보관본과 편집본을 확인한 후 선택하라.",13,GRAY));if(all.isEmpty())add(body,txt("발견된 그룹 없음",14,GRAY));int limit=Math.min(all.size(),(page+1)*15);for(int j=page*15;j<limit;j++){ScanEngine.Group g=all.get(j);LinearLayout c=card(body);add(c,bold(g.title+" #"+(j+1)+" · "+g.items.size()+"개",17,WHITE));add(c,txt(g.reason,12,GRAY));add(c,txt("보관 추천: "+g.best.name,13,RED));button(c,"그룹 비교 / 선택",true,()->compare(g));}if(page>0)button(body,"이전 그룹 페이지",false,()->{page--;show();});if(limit<all.size())button(body,"다음 그룹 페이지",false,()->{page++;show();});}
 void compare(ScanEngine.Group g){LinearLayout l=col();ScrollView sc=new ScrollView(this);sc.addView(l);for(ScanEngine.Item i:g.items){itemRow(l,i,i==g.best); }AlertDialog dialog=new AlertDialog.Builder(this).setTitle(g.title+" · "+g.items.size()+"개").setView(sc).setNegativeButton("닫기",null).setNeutralButton("보관본 제외 선택",(a,b)->{if(busy){toast("스캔 종료 후 선택");return;}for(ScanEngine.Item i:g.items)if(i!=g.best&&!i.protectedFile&&i.media)i.checked=true;g.best.checked=false;show();}).setPositiveButton("선택 확인",(a,b)->show()).create();dialog.show();}
 void files(){if(result==null){noScan();return;}EditText q=new EditText(this);q.setSingleLine(true);q.setHint("파일명·AI 태그·OCR 검색");q.setTextColor(WHITE);q.setHintTextColor(GRAY);add(body,q);LinearLayout list=col();add(body,list);q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){page=0;renderFiles(list,s.toString());}public void afterTextChanged(android.text.Editable e){}});renderFiles(list,"");}
 void renderFiles(LinearLayout list,String q){
  if(result==null)return;int generation=++filterGeneration;if(filterPending!=null)filterHandler.removeCallbacks(filterPending);ScanEngine.Result snapshot=result;int currentPage=page;
  filterPending=()->{try{filters.execute(()->{String term=q.toLowerCase(Locale.ROOT).trim();ArrayList<ScanEngine.Item> a=new ArrayList<>();for(ScanEngine.Item i:snapshot.items){if(Thread.currentThread().isInterrupted())return;if(term.isEmpty()||(i.name+" "+i.path+" "+i.labels+" "+i.text+" "+i.reason).toLowerCase(Locale.ROOT).contains(term))a.add(i);}runOnUiThread(()->{if(isDestroyed()||generation!=filterGeneration||result!=snapshot)return;thumbGeneration++;list.removeAllViews();int start=currentPage*40,lim=Math.min(a.size(),start+40);add(list,txt(a.size()+"개 · 추천 점수/용량순 · "+(currentPage+1)+"페이지",13,GRAY));for(int j=start;j<lim;j++)itemRow(list,a.get(j),false);if(currentPage>0)button(list,"이전 페이지",false,()->{page--;renderFiles(list,q);});if(lim<a.size())button(list,"다음 페이지",false,()->{page++;renderFiles(list,q);});});});}catch(RejectedExecutionException ignored){}};
  filterHandler.postDelayed(filterPending,180);
 }
 void updateCenter(){
  if(busy){toast("작업 종료 후 확인하라.");return;}
  ScanPolicy policy=ScanPolicy.load(this);
  new AlertDialog.Builder(this).setTitle("분석 정책 OTA").setMessage("현재 정책 r"+policy.revision+" · 앱 설치 없이 분석 설정만 변경. APK 엔진/권한 업데이트는 별도 설치 필요.").setNegativeButton("닫기",null).setNeutralButton("기본 정책 복구",(a,b)->{ScanPolicy.reset(this);toast("기본값으로 복구했다.");}).setPositiveButton("정책 확인",(a,b)->checkPolicy()).show();
 }
 void checkPolicy(){
  if(busy)return;busy=true;scanStatus="서명된 정책 확인 중…";show();
  worker.submit(()->{ScanPolicy.Offer offer=null;String error=null;try{offer=ScanPolicy.check(getApplicationContext());}catch(Exception e){error=e.getMessage();}final ScanPolicy.Offer available=offer;final String failure=error;
   runOnUiThread(()->{if(isDestroyed())return;busy=false;show();if(failure!=null){toast("정책 확인 실패: "+failure);return;}if(available==null){toast("새 정책 없음");return;}new AlertDialog.Builder(this).setTitle("서명 확인 완료 · r"+available.policy.revision).setMessage("썸네일 "+available.policy.thumbnail+"px · 분석 작업 "+available.policy.workers+"개 · 다음 스캔부터 적용. 파일 삭제/설치 권한 변경 없음.").setNegativeButton("취소",null).setPositiveButton("적용",(a,b)->{if(busy)return;try{toast(ScanPolicy.apply(this,available)?"적용 완료. 다음 스캔에 반영.":"이미 적용된 정책");}catch(Exception e){toast("서명 확인 실패");}}).show();});
  });
 }
 void loadThumb(ImageView view,ScanEngine.Item i){String key=i.key()+":"+i.modified+":"+i.size;android.graphics.Bitmap cached=thumbCache.get(key);if(cached!=null){view.setImageBitmap(cached);return;}int generation=thumbGeneration;try{thumbs.execute(()->{if(generation!=thumbGeneration||Thread.currentThread().isInterrupted())return;try{android.graphics.Bitmap b=getContentResolver().loadThumbnail(i.uri,new android.util.Size(128,128),null);thumbCache.put(key,b);runOnUiThread(()->{if(!isDestroyed()&&generation==thumbGeneration)view.setImageBitmap(b);});}catch(Exception ignored){}});}catch(RejectedExecutionException ignored){}}
 void itemRow(LinearLayout parent,ScanEngine.Item i,boolean best){LinearLayout c=card(parent),r=row();if(i.image()||i.video()){ImageView v=new ImageView(this);v.setImageResource(R.drawable.chad);v.setScaleType(ImageView.ScaleType.CENTER_CROP);r.addView(v,new LinearLayout.LayoutParams(dp(68),dp(68)));v.setOnClickListener(w->preview(i));loadThumb(v,i);}LinearLayout info=col();info.setPadding(dp(8),0,0,0);add(info,bold(i.name,14,WHITE));add(info,txt(i.desc(),12,GRAY));add(info,txt(i.protectedFile?"보호 중":best?"보관 추천":"추천 점수 "+i.score,12,i.protectedFile||best?GRAY:RED));weight(r,info);CheckBox ck=new CheckBox(this);ck.setContentDescription("휴지통 선택");ck.setChecked(i.checked);ck.setEnabled(!i.protectedFile&&i.media&&!busy&&!best);ck.setOnCheckedChangeListener((v,b)->{i.checked=b;updateSelection();});r.addView(ck);add(c,r);if(!i.reason.isEmpty())add(c,txt(i.reason,12,GRAY));if(!i.labels.isEmpty())add(c,txt("AI: "+i.labels,11,GRAY));LinearLayout actions=row();weight(actions,btn("열기 / 상세",false,()->preview(i)));weight(actions,btn("보관 보호",false,()->{if(busy)return;i.checked=false;i.protectedFile=true;protectedKeys.add(i.key());save("protected",protectedKeys);String k="keep:"+i.ext()+":"+ScanEngine.isScreenshot(i);prefs.edit().putInt(k,prefs.getInt(k,0)+1).apply();ck.setChecked(false);ck.setEnabled(false);toast("보호했다, BRO.");updateSelection();}));add(c,actions);if(!i.media){add(c,txt("일반 파일: 격리 후 별도 영구 삭제 가능. 원본 백업 검증 필요.",11,GRAY));if(!i.protectedFile)button(c,"안전 격리",false,()->quarantine(i));}}
 void preview(ScanEngine.Item i){LinearLayout l=col();l.setPadding(dp(15),dp(8),dp(15),dp(8));add(l,bold(i.name,18,WHITE));add(l,txt(i.path+"\n"+i.desc()+"\n"+i.mime+"\n"+i.reason,13,GRAY));if(i.image()||i.video()){ImageView v=new ImageView(this);v.setAdjustViewBounds(true);v.setMaxHeight(dp(330));add(l,v);thumbs.execute(()->{try{android.graphics.Bitmap b=getContentResolver().loadThumbnail(i.uri,new android.util.Size(800,800),null);runOnUiThread(()->v.setImageBitmap(b));}catch(Exception ignored){}});}if(!i.text.isEmpty())add(l,txt(i.text.substring(0,Math.min(600,i.text.length())),12,GRAY));if(!i.hash.isEmpty())add(l,txt("SHA-256: "+i.hash,11,GRAY));if(!i.signature.isEmpty())add(l,txt("내용 특징: "+i.signature.substring(0,Math.min(400,i.signature.length())),11,GRAY));ScrollView s=new ScrollView(this);s.addView(l);new AlertDialog.Builder(this).setView(s).setPositiveButton("원본 열기",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(i.uri,i.mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){toast("이 파일을 열 앱이 없다.");}}).setNegativeButton("닫기",null).show();}
 void updateSelection(){if(selection==null)return;int n=0;long bytes=0;if(result!=null)for(ScanEngine.Item i:result.items)if(i.checked&&!i.protectedFile&&i.media){n++;bytes+=i.size;}selection.setText(n==0?"":"선택 "+n+"개 · "+bytes(bytes)+" · 눌러서 검토");selection.setVisibility(n==0?View.GONE:View.VISIBLE);selection.setOnClickListener(v->trash());}
 void trash(){if(busy||result==null||!pending.isEmpty()||restoring)return;ArrayList<ScanEngine.Item> chosen=new ArrayList<>();for(ScanEngine.Item i:result.items)if(i.checked&&!i.protectedFile&&i.media)chosen.add(i);if(chosen.isEmpty())return;for(ScanEngine.Group g:concatGroups()){if(chosen.containsAll(g.items)){toast("그룹마다 최소 1개는 남겨라: "+g.best.name);return;}}if(chosen.size()>500){toast("한 번에 500개 이하로 선택하라.");return;}long total=chosen.stream().mapToLong(i->i.size).sum();new AlertDialog.Builder(this).setTitle("시스템 휴지통 이동").setMessage(chosen.size()+"개 · "+bytes(total)+"\n휴지통에 있는 동안 용량이 유지될 수 있다. 원본은 시스템 정책에 따라 복구 가능하다.\n이 작업은 미디어에만 적용된다.").setNegativeButton("취소",null).setPositiveButton("검증 후 이동",(d,w)->validateTrash(chosen)).show();}
 ArrayList<ScanEngine.Group> concatGroups(){ArrayList<ScanEngine.Group> g=new ArrayList<>(result.exact);g.addAll(result.similar);return g;}
 void validateTrash(ArrayList<ScanEngine.Item> chosen){ArrayList<Uri> uris=new ArrayList<>();for(ScanEngine.Item i:chosen){try(Cursor q=getContentResolver().query(i.uri,new String[]{"_size","date_modified","is_favorite","is_trashed"},null,null,null)){if(q==null||!q.moveToFirst()||q.getLong(0)!=i.size||q.getLong(1)*1000!=i.modified||q.getInt(2)!=0||q.getInt(3)!=0){toast("파일 상태 변경/보호 감지. 다시 스캔하라.");return;}uris.add(i.uri);}catch(Exception e){toast("안전 검증 실패. 이동하지 않았다.");return;}}try{pending=chosen;restoring=false;startIntentSenderForResult(MediaStore.createTrashRequest(getContentResolver(),uris,true).getIntentSender(),REQ_TRASH,null,0,0,0);}catch(Exception e){pending.clear();toast("시스템 휴지통 요청 실패");}}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(req==REQ_TREE&&code==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{if((data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)==0)throw new SecurityException("Read permission missing");if((data.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0)getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);else getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);trees.add(u.toString());save("trees",trees);result=null;toast("폴더 등록 완료");show();}catch(Exception e){toast("폴더 권한을 저장할 수 없다.");}}if(req==REQ_TRASH){if(code==RESULT_OK){if(restoring){prefs.edit().remove("lastTrash").apply();toast("시스템 복원 요청 완료");}else if(!pending.isEmpty()){long n=pending.stream().mapToLong(i->i.size).sum();org.json.JSONArray a=new org.json.JSONArray();for(ScanEngine.Item i:pending)a.put(i.key());prefs.edit().putString("lastTrash",a.toString()).putString("history",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.KOREA).format(new Date())+" · 휴지통 "+pending.size()+"개 ("+bytes(n)+")\n"+prefs.getString("history","")).putLong("candidate",-1).apply();toast("휴지통으로 이동했다, BRO.");}result=null;CleanerWidget.refresh(this);}pending.clear();restoring=false;show();}}
 void protection(){LinearLayout c=card(body);add(c,bold("보호 파일 "+protectedKeys.size()+"개",20,WHITE));add(c,txt("즐겨찾기·업무 키워드·중요 문서는 기본 보호. 아래 키워드가 포함된 경로도 보호한다.",13,GRAY));EditText e=new EditText(this);e.setHint("예: DCIM/Work, 촬영");e.setTextColor(WHITE);add(c,e);button(c,"보호 키워드 추가",true,()->{if(busy)return;String v=e.getText().toString().trim();if(!v.isEmpty()){protectedPaths.add(v);save("paths",protectedPaths);result=null;show();}});for(String p:protectedPaths)button(c,p+" · 해제",false,()->{if(busy)return;protectedPaths.remove(p);save("paths",protectedPaths);result=null;show();});for(String k:protectedKeys)button(c,k+" · 해제",false,()->{if(busy)return;protectedKeys.remove(k);save("protected",protectedKeys);result=null;show();});button(body,"일반 파일 폴더 추가",false,this::chooseTree);for(String t:trees)button(body,"폴더 해제: "+t,false,()->{if(busy)return;trees.remove(t);save("trees",trees);try{getContentResolver().releasePersistableUriPermission(Uri.parse(t),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}result=null;show();});}
 void history(){quarantineList(body);LinearLayout c=card(body);add(c,bold("청소 기록",20,WHITE));add(c,txt(prefs.getString("history","아직 기록 없음"),14,GRAY));button(c,"최근 휴지통 이동 복원 요청",true,()->{if(busy||!pending.isEmpty()||restoring)return;try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("lastTrash","[]"));ArrayList<Uri> uris=new ArrayList<>();for(int j=0;j<a.length();j++)uris.add(Uri.parse(a.getString(j)));if(uris.isEmpty()){toast("복원 기록 없음");return;}restoring=true;startIntentSenderForResult(MediaStore.createTrashRequest(getContentResolver(),uris,false).getIntentSender(),REQ_TRASH,null,0,0,0);}catch(Exception e){restoring=false;toast("복원 불가. 갤러리 휴지통을 확인하라.");}});}
 void quarantine(ScanEngine.Item i){if(busy||i.protectedFile||result==null)return;for(ScanEngine.Group g:concatGroups())if(g.best==i){toast("그룹 보관 추천 파일은 격리할 수 없다.");return;}new AlertDialog.Builder(this).setTitle("일반 파일 안전 격리").setMessage(i.name+"\n"+bytes(i.size)+"\n앱 내부에 검증된 복사본을 만든 뒤 원본을 제거한다. 격리함을 비워야 실제 용량이 확보된다. 앱 삭제 전에 복원하라.").setNegativeButton("취소",null).setPositiveButton("격리",(d,w)->doJob(()->{new Quarantine(getApplicationContext()).move(i);},"격리 완료")).show();}
 interface Operation {void run()throws Exception;}
 void doJob(Operation op,String message){if(busy||!pending.isEmpty()||restoring)return;busy=true;show();job=worker.submit(()->{String outcome=message;try{op.run();}catch(Exception e){outcome="실패/백업 확인 필요: "+e.getMessage();}String finalOutcome=outcome;runOnUiThread(()->{if(isDestroyed())return;busy=false;result=null;prefs.edit().putLong("candidate",-1).apply();CleanerWidget.refresh(this);show();toast(finalOutcome);});});}
 void quarantineList(LinearLayout parent){LinearLayout c=card(parent);add(c,bold("일반 파일 격리함",18,WHITE));add(c,txt("앱 삭제 시 격리본도 삭제된다. 복원 또는 영구 삭제를 선택하라.",12,GRAY));Quarantine q=new Quarantine(this);for(Quarantine.Entry e:q.entries()){add(c,txt(e.name()+" · "+bytes(e.size()),14,WHITE));LinearLayout r=row();weight(r,btn("복원",false,()->doJob(()->q.restore(e),"복원 완료")));weight(r,btn("영구 삭제",true,()->new AlertDialog.Builder(this).setTitle("복구할 수 없다").setMessage(e.name()+"\n정말 영구 삭제할 것인가?").setNegativeButton("취소",null).setPositiveButton("영구 삭제",(d,w)->doJob(()->q.purge(e),"격리본 영구 삭제 완료")).show()));add(c,r);}}
 void apps(){android.app.usage.UsageStatsManager m=(android.app.usage.UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);long now=System.currentTimeMillis();List<android.app.usage.UsageStats> stats=m.queryUsageStats(android.app.usage.UsageStatsManager.INTERVAL_MONTHLY,now-90L*86400000,now);if(stats==null||stats.isEmpty()){new AlertDialog.Builder(this).setMessage("미사용 앱 분석에는 사용정보 접근 권한이 필요하다.").setPositiveButton("권한 설정",(a,b)->settings(Settings.ACTION_USAGE_ACCESS_SETTINGS)).setNegativeButton("닫기",null).show();return;}Map<String,Long> latest=new HashMap<>();for(android.app.usage.UsageStats u:stats)latest.merge(u.getPackageName(),u.getLastTimeUsed(),Math::max);ArrayList<String> candidates=new ArrayList<>();for(Map.Entry<String,Long> u:latest.entrySet())if(u.getValue()>0&&u.getValue()<now-30L*86400000)candidates.add(u.getKey());Collections.sort(candidates);new AlertDialog.Builder(this).setTitle("30일 이상 사용 기록 없는 앱 (기록 존재 앱만)").setItems(candidates.toArray(new String[0]),(a,b)->{try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+candidates.get(b))));}catch(Exception e){toast("시스템 설정에서 확인");}}).setNegativeButton("닫기",null).show();}
 @Override protected void onDestroy(){filterHandler.removeCallbacksAndMessages(null);filters.shutdownNow();thumbs.shutdownNow();worker.shutdownNow();super.onDestroy();}
}
